/**
 * Typed access to models.json — the pinned model files mirrored to our Hugging Face repos.
 * Generated by scripts/models/publish_models.py; do not edit by hand.
 */
import manifestJson from '../../models.json'

export interface ManifestFile {
  /** Path inside the repo, e.g. "onnx/encoder_model.onnx". */
  path: string
  size: number
  sha256: string
  url: string | null
}

export interface ManifestModel {
  task: string
  repo: string
  /** Commit hash on Hugging Face; null if the mirror was never published. */
  revision: string | null
  license: string
  upstream: string
  source: { repo: string; revision: string }
  files: ManifestFile[]
}

export interface ModelManifest {
  schemaVersion: 1
  models: Record<string, ManifestModel>
}

export const manifest = manifestJson as ModelManifest

/** Mirror entry for a model id, or null if it has not been published yet. */
export function mirroredModel(id: string): (ManifestModel & { revision: string }) | null {
  const entry = manifest.models[id]
  return entry?.revision ? (entry as ManifestModel & { revision: string }) : null
}
